// Conversion goldens of the native WASAPI backend's `convert` tests (ADR 0046, decision 3): what
// the cpal adapter's conversion (cpal 0.16.0, the pinned fork at commit 31b5dd4) makes of
// `input()`, captured at c5b93418 so the tests keep their byte-identity claim without cpal.
//
// The tables below the marker are generated by `transit-playback`'s test
// `backend::cpal_convert_golden::the_wasapi_conversion_goldens_are_cpals_conversion`, which also
// checks them against cpal on every target that still builds cpal. To regenerate, run it with
// `CONVERT_GOLDEN_OUT=crates/audio-wasapi/src/convert_golden.rs` (a path from the repository
// root), then `cargo fmt --all`, and diff. Everything above the marker is kept as it is.
//
// Plain comments, not module docs: `transit-playback` includes this file with `include!`.

/// The sample set of the conversion tests: a ramp across `[-0.999, 0.999)` and edge values.
pub(crate) fn input() -> Vec<f32> {
    let mut v: Vec<f32> = (0..2048).map(|i| (i as f32 / 1024.0 - 1.0) * 0.999).collect();
    v.extend([-1.0, 0.0, 0.5, -0.5, 0.999_999, 1e-9, -1e-9, 0.123_456_79]);
    v
}

